#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line); // Read first line and ignore
    getline(cin, line); // Read second line

    // Split the line by parentheses with optional letters inside
    vector<string> parts;
    size_t start = 0, end = 0;
    for (size_t i = 0; i < line.size(); ++i) {
        if (line[i] == '(') {
            start = i + 1;
        } else if (line[i] == ')') {
            end = i;
            parts.push_back(line.substr(start, end - start));
        }
    }

    int maxWord = 0;
    for (const auto& part : parts) {
        // Split by underscores
        stringstream ss(part);
        string token;
        while (getline(ss, token, '_')) {
            maxWord = max(maxWord, (int)token.length());
        }
    }

    int countInParentheses = 0;
    int tempCount = 0;
    bool inParen = false;
    bool counted = false;
    for (char ch : line) {
        if (ch == '(') {
            inParen = true;
        } else if (ch == ')') {
            inParen = false;
            counted = false;
        } else if (inParen && isalpha(ch)) {
            if (counted) continue;
            countInParentheses++;
            counted = true;
        } else if (ch == '_') {
            counted = false;
        }
    }

    cout << maxWord << " " << countInParentheses << "\n";

    return 0;
}
